Object.assign(SNIP,{});PRESET_NOTES["l72"]={"Ví dụ: Bước 1 — trâu bò O(n³)": "Đoạn tốt nhất là 3, −1, 4 với tổng 6. Đúng nhưng tốn 84 phép cộng cho n = 7; với n = 10^5 là khoảng 1,7 · 10^14.", "Ví dụ: Bước 2 — bỏ việc lặp, O(n²)": "Nhận ra vòng k tính lại tổng đã có ở bước trước: giữ s và cộng dồn. Còn 28 phép cộng — n(n + 1)/2.", "Ví dụ: Bước 3 — Kadane O(n)": "Đổi câu hỏi “đoạn nào?” thành “đoạn tốt nhất kết thúc tại j?”: chỉ có hai lựa chọn, một vòng lặp là đủ. Đây là quy hoạch động một chiều.", "Ví dụ: Tra cứu nhanh bằng bảng băm": "Đếm cặp i < j có a[i] + a[j] = 6: (1, 5), (1, 5), (7, −1) — 3 cặp. Trâu bò thử mọi cặp O(n²); câu hỏi “đã gặp K − x bao nhiêu lần?” thì bảng băm trả lời trong O(1).", "Lỗi: khởi tạo đáp án bằng 0": "In 0 — tổng của đoạn rỗng, không hợp lệ. Lời giải trâu bò sẽ bắt được lỗi này ngay khi thử bộ toàn số âm: khởi tạo bằng a[0] (hoặc −∞)."};EX_HINTS["l72"]=[["Bắt đầu bằng lời giải O(n²): với mỗi i, cộng dồn s khi j tăng. Rồi tối ưu.", "ketThuc = tổng lớn nhất của đoạn kết thúc đúng tại ngày j = max(a[j], ketThuc + a[j]). Đáp án = max mọi ketThuc.", "Khởi tạo bằng a[0], không phải 0 (đoạn phải có ít nhất một ngày). Tổng tới 10^15: long long."], ["Trâu bò: hai vòng lặp i < j, O(n²). Câu hỏi lặp lại là “bên trái j có bao nhiêu số bằng a_j − K hoặc a_j + K?”", "Bảng băm đếm số lần đã gặp mỗi giá trị trả lời câu đó trong O(1).", "K = 0: x − K và x + K trùng nhau, đừng đếm hai lần. Số cặp tới n²/2: long long. (Cách khác: sắp xếp rồi dùng hai con trỏ.)"], ["Trâu bò: mọi (l, r) với tổng cộng dồn, O(n²).", "Quan sát: các số không âm, nên khi r tăng thì l tốt nhất không bao giờ lùi lại. Đó là dấu hiệu của hai con trỏ (bài 28).", "Với mỗi r: cộng a[r]; khi tổng > S thì bỏ a[l], l++. Độ dài r − l + 1 (có thể 0 nếu a[r] > S)."]];
/* ===================== BÀI 72 · Tiếp cận một bài toán lạ: từ trâu bò đến tối ưu ===================== */
/* Bài 72 · Tiếp cận một bài toán lạ: từ trâu bò đến tối ưu
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR72=[{label:"Ví dụ: Bước 1 — trâu bò O(n³)",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {2, -5, 3, -1, 4, -2, 1};\n    int n = a.size();\n    long long tot = a[0];\n    int dem = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = i; j < n; j++) {\n            long long s = 0;\n            for (int k = i; k <= j; k++) { s += a[k]; dem++; }   // cộng lại từ đầu\n            tot = max(tot, s);\n        }\n    cout << tot << \" (\" << dem << \" phep cong)\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","j","k"]},{type:"vars",names:["s","tot","dem"]}],py:{code:"a = [2, -5, 3, -1, 4, -2, 1]\nn = len(a)\ntot = a[0]\ndem = 0\nfor i in range(n):\n    for j in range(i, n):\n        s = 0\n        for k in range(i, j + 1):      # cộng lại từ đầu\n            s += a[k]\n            dem += 1\n        tot = max(tot, s)\nprint(tot, \"(\" + str(dem) + \" phep cong)\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] a = { 2, -5, 3, -1, 4, -2, 1 };\n        int n = a.Length;\n        long tot = a[0];\n        int dem = 0;\n        for (int i = 0; i < n; i++)\n            for (int j = i; j < n; j++)\n            {\n                long s = 0;\n                for (int k = i; k <= j; k++) { s += a[k]; dem++; }   // cộng lại từ đầu\n                tot = Math.Max(tot, s);\n            }\n        Console.WriteLine(tot + \" (\" + dem + \" phep cong)\");\n    }\n}"}},{label:"Ví dụ: Bước 2 — bỏ việc lặp, O(n²)",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {2, -5, 3, -1, 4, -2, 1};\n    int n = a.size();\n    long long tot = a[0];\n    int dem = 0;\n    for (int i = 0; i < n; i++) {\n        long long s = 0;\n        for (int j = i; j < n; j++) {\n            s += a[j];                 // tổng a[i..j] = tổng a[i..j-1] + a[j]\n            dem++;\n            tot = max(tot, s);\n        }\n    }\n    cout << tot << \" (\" << dem << \" phep cong)\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","j"]},{type:"vars",names:["s","tot","dem"]}],py:{code:"a = [2, -5, 3, -1, 4, -2, 1]\nn = len(a)\ntot = a[0]\ndem = 0\nfor i in range(n):\n    s = 0\n    for j in range(i, n):\n        s += a[j]                      # tổng a[i..j] = tổng a[i..j-1] + a[j]\n        dem += 1\n        tot = max(tot, s)\nprint(tot, \"(\" + str(dem) + \" phep cong)\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] a = { 2, -5, 3, -1, 4, -2, 1 };\n        int n = a.Length;\n        long tot = a[0];\n        int dem = 0;\n        for (int i = 0; i < n; i++)\n        {\n            long s = 0;\n            for (int j = i; j < n; j++)\n            {\n                s += a[j];                     // tổng a[i..j] = tổng a[i..j-1] + a[j]\n                dem++;\n                tot = Math.Max(tot, s);\n            }\n        }\n        Console.WriteLine(tot + \" (\" + dem + \" phep cong)\");\n    }\n}"}},{label:"Ví dụ: Bước 3 — Kadane O(n)",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {2, -5, 3, -1, 4, -2, 1};\n    int n = a.size();\n    long long ketThuc = a[0], tot = a[0];   // ketThuc: đoạn tốt nhất kết thúc tại j\n    for (int j = 1; j < n; j++) {\n        ketThuc = max(a[j], ketThuc + a[j]);   // bắt đầu lại tại j, hoặc nối thêm a[j]\n        tot = max(tot, ketThuc);\n    }\n    cout << tot << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"vars",names:["ketThuc","tot"]}],py:{code:"a = [2, -5, 3, -1, 4, -2, 1]\nn = len(a)\nket_thuc = tot = a[0]                  # ket_thuc: đoạn tốt nhất kết thúc tại j\nfor j in range(1, n):\n    ket_thuc = max(a[j], ket_thuc + a[j])   # bắt đầu lại tại j, hoặc nối thêm a[j]\n    tot = max(tot, ket_thuc)\nprint(tot)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] a = { 2, -5, 3, -1, 4, -2, 1 };\n        int n = a.Length;\n        long ketThuc = a[0], tot = a[0];       // ketThuc: đoạn tốt nhất kết thúc tại j\n        for (int j = 1; j < n; j++)\n        {\n            ketThuc = Math.Max(a[j], ketThuc + a[j]);   // bắt đầu lại tại j, hoặc nối thêm a[j]\n            tot = Math.Max(tot, ketThuc);\n        }\n        Console.WriteLine(tot);\n    }\n}"}},{label:"Ví dụ: Tra cứu nhanh bằng bảng băm",input:"",code:"#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 5, 7, -1, 5};\n    int K = 6;\n    long long dem = 0;\n    unordered_map<int, int> daGap;     // giá trị → số lần đã gặp ở bên trái\n    for (int x : a) {\n        if (daGap.count(K - x)) dem += daGap[K - x];   // ghép x với mọi K − x đã gặp\n        daGap[x]++;\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["x","dem"]}],py:{code:"a = [1, 5, 7, -1, 5]\nK = 6\ndem = 0\nda_gap = {}                            # giá trị → số lần đã gặp ở bên trái\nfor x in a:\n    dem += da_gap.get(K - x, 0)        # ghép x với mọi K − x đã gặp\n    da_gap[x] = da_gap.get(x, 0) + 1\nprint(dem)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 5, 7, -1, 5 };\n        int K = 6;\n        long dem = 0;\n        var daGap = new Dictionary<int, int>();   // giá trị → số lần đã gặp ở bên trái\n        foreach (int x in a)\n        {\n            if (daGap.ContainsKey(K - x)) dem += daGap[K - x];   // ghép x với mọi K − x đã gặp\n            daGap[x] = daGap.ContainsKey(x) ? daGap[x] + 1 : 1;\n        }\n        Console.WriteLine(dem);\n    }\n}"}},{label:"Lỗi: khởi tạo đáp án bằng 0",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {-3, -1, -4};\n    long long ketThuc = 0, tot = 0;    // SAI: đoạn phải khác rỗng, mà mọi số đều âm\n    for (long long x : a) {\n        ketThuc = max(x, ketThuc + x);\n        tot = max(tot, ketThuc);\n    }\n    cout << tot << \"\\n\";               // đúng phải là -1\n    return 0;\n}",viz:[{type:"vars",names:["x","ketThuc","tot"]}],py:{code:"a = [-3, -1, -4]\nket_thuc = tot = 0                     # SAI: đoạn phải khác rỗng, mà mọi số đều âm\nfor x in a:\n    ket_thuc = max(x, ket_thuc + x)\n    tot = max(tot, ket_thuc)\nprint(tot)                             # đúng phải là -1"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] a = { -3, -1, -4 };\n        long ketThuc = 0, tot = 0;             // SAI: đoạn phải khác rỗng, mà mọi số đều âm\n        foreach (long x in a)\n        {\n            ketThuc = Math.Max(x, ketThuc + x);\n            tot = Math.Max(tot, ketThuc);\n        }\n        Console.WriteLine(tot);                // đúng phải là -1\n    }\n}"}}];
