makeEx2(document.getElementById("ex-l72"),sim72,[{t:"Chuỗi ngày lãi nhất",d:"Lãi (có thể âm) của một cửa hàng trong n ngày là a_1 … a_n. Tìm tổng lãi lớn nhất của một chuỗi ngày liên tiếp (ít nhất một ngày). Đầu vào: n (1 ≤ n ≤ 10^6) rồi n số (|a_i| ≤ 10^9). Đầu ra: một số.",tests:[{in:"7\n2 -5 3 -1 4 -2 1",out:"6"},{in:"3\n-3 -1 -4",out:"-1"},{in:"1\n5",out:"5"},{in:"5\n1000000000 1000000000 1000000000 1000000000 1000000000",out:"5000000000"},{in:"4\n-1000000000 1000000000 -1 1000000000",out:"1999999999"},{in:"50\n-82 100 52 89 -53 -12 78 39 58 -5 -22 89 83 75 53 -67 79 77 -13 -41 -3 -64 62 -94 77 -44 16 -97 14 -83 97 -25 -77 29 -19 85 -96 6 -35 -32 -12 -6 -44 -5 24 62 -37 -11 51 27",out:"713"},{in:"40\n497318587 -603233865 -355558202 -123511501 944434420 818255404 226996199 -279393947 -670589271 -26140925 878612587 -534735657 -909862473 -881981352 -291683108 -101311754 -868514215 -189550624 -843362250 825757762 971339949 -685317923 -359477616 -869126547 -51858411 50106040 -911138164 856989524 423696354 161035204 47904792 185982865 877285997 959169875 -157727525 -496940025 -740514052 689887914 787838900 72487777",out:"3667097600"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    // bước 1: trâu bò; bước 2: cộng dồn; bước 3: đoạn tốt nhất kết thúc tại j\n    cout << 0 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%201)-100).join(" "),ns:[250,500,1000,2000],need:"n",limit:n=>40*n+300,why:"Thử mọi điểm bắt đầu và cộng dồn tốn O(n²)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# bước 1: trâu bò; bước 2: cộng dồn; bước 3: đoạn tốt nhất kết thúc tại j\nprint(0)",hints:["Bắt đầu bằng lời giải O(n²): với mỗi i, cộng dồn s khi j tăng. Rồi tối ưu.","ket_thuc = tổng lớn nhất của đoạn kết thúc đúng tại ngày j = max(a[j], ket_thuc + a[j]). Đáp án = max mọi ket_thuc.","Khởi tạo bằng a[0], không phải 0 (đoạn phải có ít nhất một ngày)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        // bước 1: trâu bò; bước 2: cộng dồn; bước 3: đoạn tốt nhất kết thúc tại j\n        Console.WriteLine(0);\n    }\n}",hints:["Bắt đầu bằng lời giải O(n²): với mỗi i, cộng dồn s khi j tăng. Rồi tối ưu.","ketThuc = tổng lớn nhất của đoạn kết thúc đúng tại ngày j = Math.Max(a[j], ketThuc + a[j]). Đáp án = max mọi ketThuc.","Khởi tạo bằng a[0], không phải 0. Tổng tới 10^15: long."]}},{t:"Cặp chênh lệch",d:"Cho n số nguyên a_1 … a_n và số K ≥ 0. Đếm số cặp chỉ số i < j sao cho |a_i − a_j| = K. Đầu vào: n K (1 ≤ n ≤ 2·10^5, 0 ≤ K ≤ 10^9) rồi n số (0 ≤ a_i ≤ 10^9). Đầu ra: một số.",tests:[{in:"5 2\n1 5 3 4 2",out:"3"},{in:"4 0\n1 1 1 1",out:"6"},{in:"1 3\n7",out:"0"},{in:"5 10\n1 2 3 4 5",out:"0"},{in:"5 2\n1 3 1 3 5",out:"6"},{in:"50 3\n17 2 8 14 10 15 1 2 9 20 9 11 7 6 16 8 4 3 13 0 1 20 15 6 18 0 10 6 19 6 3 10 14 7 11 18 20 6 0 16 19 15 4 12 3 19 20 10 9 15",out:"96"},{in:"60 0\n9 2 4 0 10 7 2 8 8 6 6 0 5 1 3 8 9 6 5 7 0 8 3 9 5 0 5 10 9 1 2 1 6 0 1 0 5 9 8 10 5 5 0 9 0 8 3 10 1 3 4 6 1 1 4 3 2 0 9 1",out:"157"}],start:"#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n;\n    long long K;\n    cin >> n >> K;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    long long dem = 0;\n    // với mỗi x: đã gặp bao nhiêu số bằng x − K và x + K?\n    cout << dem << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" 3\n"+Array.from({length:n},(_,i)=>(i*7)%(2*n)).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+300,why:"Thử mọi cặp tốn O(n²)."},py:{start:"n, K = map(int, input().split())\na = list(map(int, input().split()))\ndem = 0\n# với mỗi x: đã gặp bao nhiêu số bằng x − K và x + K?\nprint(dem)",hints:["Trâu bò: hai vòng lặp i < j, O(n²). Câu hỏi lặp lại là “bên trái j có bao nhiêu số bằng a_j − K hoặc a_j + K?”","dict (hoặc collections.Counter) đếm số lần đã gặp mỗi giá trị trả lời câu đó trong O(1).","K = 0: x − K và x + K trùng nhau, đừng đếm hai lần."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] h = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int n = (int)h[0];\n        long K = h[1];\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long dem = 0;\n        // với mỗi x: đã gặp bao nhiêu số bằng x − K và x + K?\n        Console.WriteLine(dem);\n    }\n}",hints:["Trâu bò: hai vòng lặp i < j, O(n²). Câu hỏi lặp lại là “bên trái j có bao nhiêu số bằng a_j − K hoặc a_j + K?”","Dictionary<long, long> đếm số lần đã gặp mỗi giá trị trả lời câu đó trong O(1).","K = 0: x − K và x + K trùng nhau, đừng đếm hai lần. Số cặp tới n²/2: long."]}},{t:"Ngân sách du lịch",d:"Chi phí của n điểm tham quan trên một con đường là a_1 … a_n (không âm). Bạn muốn đi một dãy điểm liên tiếp có tổng chi phí không quá S. Tìm số điểm nhiều nhất có thể đi (có thể là 0). Đầu vào: n S (1 ≤ n ≤ 10^6, 0 ≤ S ≤ 10^15) rồi n số (0 ≤ a_i ≤ 10^9). Đầu ra: một số.",tests:[{in:"6 5\n2 1 3 1 1 4",out:"3"},{in:"3 4\n5 5 5",out:"0"},{in:"3 0\n0 0 0",out:"3"},{in:"1 1\n1",out:"1"},{in:"7 5\n3 1 2 1 1 10 1",out:"4"},{in:"50 25\n2 5 10 0 10 8 5 1 8 10 2 7 10 1 10 3 10 7 1 6 1 8 6 8 9 8 10 4 9 6 4 5 2 2 6 1 1 9 4 8 7 4 2 10 4 8 10 8 9 9",out:"7"},{in:"40 3000000000\n671381314 523743851 884981624 822046523 813393726 751559742 268217556 546847992 915184855 802454199 2542369 693824967 709410715 79548647 845977516 154879785 469982481 416202574 347740930 337729070 39220361 743250472 462344772 506331087 225725978 733490467 988148922 768285857 96501637 324263778 574641936 5551851 285517028 380870466 974321507 357688330 569374781 804928715 51227315 259911527",out:"8"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    long long S;\n    cin >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    int tot = 0;\n    // hai con trỏ: mở rộng bên phải, thu hẹp bên trái khi tổng vượt S\n    cout << tot << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+(n*3)+"\n"+Array.from({length:n},(_,i)=>i%7).join(" "),ns:[250,500,1000,2000],need:"n",limit:n=>60*n+300,why:"Thử mọi đoạn tốn O(n²)."},py:{start:"n, S = map(int, input().split())\na = list(map(int, input().split()))\ntot = 0\n# hai con trỏ: mở rộng bên phải, thu hẹp bên trái khi tổng vượt S\nprint(tot)",hints:["Trâu bò: mọi (l, r) với tổng cộng dồn, O(n²).","Các số không âm, nên khi r tăng thì l tốt nhất không bao giờ lùi lại: hai con trỏ.","Với mỗi r: cộng a[r]; khi tổng > S thì bỏ a[l], l += 1. Độ dài r − l + 1."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] h = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int n = (int)h[0];\n        long S = h[1];\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int tot = 0;\n        // hai con trỏ: mở rộng bên phải, thu hẹp bên trái khi tổng vượt S\n        Console.WriteLine(tot);\n    }\n}",hints:["Trâu bò: mọi (l, r) với tổng cộng dồn, O(n²).","Các số không âm, nên khi r tăng thì l tốt nhất không bao giờ lùi lại: hai con trỏ.","Với mỗi r: cộng a[r]; khi tổng > S thì bỏ a[l], l++. Độ dài r − l + 1."]}}]);

